#include "simulator.hpp"
#include "types.hpp"
#include <fstream>
#include <iostream>

// Reads the text file generated by Python into the memoryTrace vector
bool Simulator::loadTrace(const std::string& filepath) {
    std::ifstream file(filepath);
    if (!file.is_open()) {
        std::cerr << "Error: Could not open trace file at " << filepath << "\n";
        return false;
    }

    PageID pageRequest;
    memoryTrace.clear();
    
    // Read every integer from the file and push it into our vector
    while (file >> pageRequest) {
        memoryTrace.push_back(pageRequest);
    }
    
    file.close();
    std::cout << "Successfully loaded " << memoryTrace.size() << " memory accesses.\n";
    return true;
}

// Runs the loaded trace against whatever algorithm is passed in
FaultCount Simulator::run(Policy* algorithm) {
    if (memoryTrace.empty()) {
        std::cerr << "Warning: Memory trace is empty. Did you load a file?\n";
        return 0;
    }

    FaultCount pageFaults = 0;
    
    // Blast every page request through the algorithm
    for (PageID pageID : memoryTrace) {
        if (algorithm->accessPage(pageID)) {
            pageFaults++; // The algorithm returned true, meaning it was a fault
        }
    }
    
    return pageFaults;
}